//! Server-generated identifiers: `<prefix>_<ULID>`.
//!
//! Ids are always generated by the server and validated on parse, so no user-controlled
//! string ever reaches a filesystem path or the engine command line.

use std::fmt;
use std::str::FromStr;

use serde::{Deserialize, Deserializer, Serialize, Serializer};
use ulid::Ulid;

#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
#[error("invalid {kind} id")]
pub struct InvalidId {
    pub kind: &'static str,
}

macro_rules! id_type {
    ($name:ident, $prefix:literal) => {
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
        pub struct $name(Ulid);

        impl $name {
            pub const PREFIX: &'static str = $prefix;

            /// A new id. ULIDs sort by creation time, which keeps listings stable.
            pub fn generate() -> Self {
                Self(Ulid::generate())
            }

            pub const fn from_ulid(ulid: Ulid) -> Self {
                Self(ulid)
            }
        }

        impl fmt::Display for $name {
            fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
                write!(f, "{}_{}", $prefix, self.0)
            }
        }

        impl FromStr for $name {
            type Err = InvalidId;

            fn from_str(s: &str) -> Result<Self, Self::Err> {
                let err = InvalidId { kind: $prefix };
                let rest = s
                    .strip_prefix($prefix)
                    .and_then(|r| r.strip_prefix('_'))
                    .ok_or(err.clone())?;
                // Canonical form only: 26 upper-case Crockford base32 characters.
                if rest.len() != 26 || rest.bytes().any(|b| b.is_ascii_lowercase()) {
                    return Err(err);
                }
                Ulid::from_string(rest).map(Self).map_err(|_| err)
            }
        }

        impl Serialize for $name {
            fn serialize<S: Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
                s.collect_str(self)
            }
        }

        impl<'de> Deserialize<'de> for $name {
            fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
                let s = String::deserialize(d)?;
                s.parse().map_err(serde::de::Error::custom)
            }
        }
    };
}

id_type!(VoiceId, "voice");
id_type!(JobId, "job");
id_type!(ConsentId, "cns");

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn round_trips_through_display_and_parse() {
        let id = VoiceId::from_ulid(Ulid::from_parts(1_700_000_000_000, 42));
        let s = id.to_string();
        assert!(s.starts_with("voice_"));
        assert_eq!(s.parse::<VoiceId>().unwrap(), id);
    }

    #[test]
    fn rejects_wrong_prefix_and_path_like_input() {
        let job = JobId::from_ulid(Ulid::from_parts(1, 2)).to_string();
        assert!(job.parse::<VoiceId>().is_err());
        for bad in [
            "",
            "voice_",
            "voice_../../etc/passwd",
            "voice_01ARZ3NDEKTSV4RRFFQ69G5FA",
            "voice_01arz3ndektsv4rrffq69g5fav",
            "voice-01ARZ3NDEKTSV4RRFFQ69G5FAV",
        ] {
            assert!(bad.parse::<VoiceId>().is_err(), "{bad}");
        }
    }
}
